function Get-DistroShelfProfileManifestPath { param([Parameter(Mandatory)][string]$AttemptRoot) Join-Path $AttemptRoot 'metadata\profile.json' }
function Write-DistroShelfProfileManifest { param([Parameter(Mandatory)]$Profile,[Parameter(Mandatory)][string]$Path,[Parameter(Mandatory)][string]$ProfileHash,[Parameter(Mandatory)]$Acceptance) $value=[ordered]@{SchemaVersion=1;Id=$Profile.Id;Name=$Profile.Name;Distro=$Profile.Distro;WslName=$Profile.WslName;Terminal=$Profile.Terminal;ProfileHash=$ProfileHash;Acceptance=$Acceptance;CommittedAt=[DateTime]::UtcNow.ToString('o')};$parent=Split-Path -Parent $Path;if(!(Test-Path $parent)){New-Item -ItemType Directory -Path $parent -Force|Out-Null};$tmp="$Path.tmp";$value|ConvertTo-Json -Depth 30|Set-Content $tmp -Encoding UTF8;Move-Item $tmp $Path -Force;return [pscustomobject]$value }
